class Solution {
public:
    vector<int> parent;
    vector<int> rank_;

    int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    void unite(int x, int y) {
        int rx = find(x), ry = find(y);
        if (rx == ry) return;
        if (rank_[rx] < rank_[ry]) swap(rx, ry);
        parent[ry] = rx;
        if (rank_[rx] == rank_[ry]) rank_[rx]++;
    }

    vector<bool> distanceLimitedPathsExist(int n, vector<vector<int>>& edgeList, vector<vector<int>>& queries) {
        parent.resize(n);
        rank_.resize(n, 0);
        for (int i = 0; i < n; i++) parent[i] = i;

        int m = edgeList.size();
        int q = queries.size();

        sort(edgeList.begin(), edgeList.end(), [](const vector<int>& a, const vector<int>& b) {
            return a[2] < b[2];
        });

        vector<int> qidx(q);
        for (int i = 0; i < q; i++) qidx[i] = i;
        sort(qidx.begin(), qidx.end(), [&](int a, int b) {
            return queries[a][2] < queries[b][2];
        });

        vector<bool> ans(q, false);
        int ei = 0;
        for (int i = 0; i < q; i++) {
            int idx = qidx[i];
            int limit = queries[idx][2];
            while (ei < m && edgeList[ei][2] < limit) {
                unite(edgeList[ei][0], edgeList[ei][1]);
                ei++;
            }
            ans[idx] = (find(queries[idx][0]) == find(queries[idx][1]));
        }

        return ans;
    }
};
